package cache

type Cache struct {
	items map[string]string
}

func (c *Cache) Put(k, v string) {
	c.items[k] = v
}

func (c *Cache) Get(k string) string {
	return c.items[k]
}

package cache

type Cache struct {
	items map[string]string
}

func (c *Cache) Put(k, v string) {
	if c.items == nil {
		c.items = map[string]string{}
	}
	c.items[k] = v
}

package store

import "database/sql"

func Find(db *sql.DB, name string) (*sql.Rows, error) {
	return db.Query("SELECT id FROM users WHERE name = '" + name + "'")
}

package store

import "database/sql"

func Find(db *sql.DB, name string) (*sql.Rows, error) {
	return db.Query("SELECT id FROM users WHERE name = ?", name)
}

package x

import "os"

func Size(path string) (int64, error) {
	f, err := os.Open(path)
	if err != nil {
		return 0, err
	}
	info, err := f.Stat()
	if err != nil {
		return 0, err
	}
	return info.Size(), nil
}

package x

import "os"

func Size(path string) (int64, error) {
	f, err := os.Open(path)
	if err != nil {
		return 0, err
	}
	defer f.Close()
	info, err := f.Stat()
	if err != nil {
		return 0, err
	}
	return info.Size(), nil
}

package m

func Name() string {
	return "adder"
}

func Sum(xs []int32) int32 {
	var t int32
	for _, x := range xs {
		t += x
	}
	return t
}
